import {solutions,polynomial} from "../../lib/math.mjs";
export type Parameters=Record<string,number|number[]>;
export type ExpandedQuestion={prompt:string;equation:string;expected:string;options:string[];parameters:Parameters};
const gcd=(a:number,b:number):number=>b?gcd(b,a%b):Math.abs(a);
export function fraction(a:number,b:number){if(!b)throw Error("Zero denominator");const g=gcd(a,b);return b/g===1?String(a/g):`${a/g}/${b/g}`;}
const pair=(x:number,y:number)=>`(${x}, ${y})`;
const pi=(n:number,unit:string)=>`${n}π ${unit}`;
const ensure=(ok:boolean)=>{if(!ok)throw Error("Generated question failed independent verification");};
export function verifyExpanded(id:string,p:Parameters,answer:string){
 const v=p as Record<string,number>;let expected='';
 switch(id){
 case 'hcf-lcm':{let h=1;for(let i=1;i<=Math.min(v.x,v.y);i++)if(v.x%i===0&&v.y%i===0)h=i;let l=Math.max(v.x,v.y);while(l%v.x||l%v.y)l++;expected=`HCF ${h}, LCM ${l}`;break;}
 case 'polynomial-zero':expected=v.a*v.r*v.r+v.b*v.r+v.c===0?'Yes, it is a zero':'No, it is not a zero';break;
 case 'coefficients':expected=`sum ${fraction(-v.b,v.a)}, product ${fraction(v.c,v.a)}`;break;
 case 'linear-elimination':case 'linear-substitution':{const d=v.A*v.E-v.B*v.D;ensure(d!==0);expected=pair((v.C*v.E-v.B*v.F)/d,(v.A*v.F-v.C*v.D)/d);break;}
 case 'linear-consistency':expected=v.A*v.E!==v.B*v.D?'One solution':v.A*v.F===v.C*v.D&&v.B*v.F===v.C*v.E?'Infinitely many solutions':'No solution';break;
 case 'quadratic-standard':expected=`a=${v.a}, b=${v.b}, c=${v.c}`;ensure(v.a!==0);break;
 case 'quadratic-roots':{const roots=solutions(`${v.a}*x^2+(${v.b})*x+(${v.c})=0`).roots;expected=[...roots].sort((a:string,b:string)=>Number(a)-Number(b)).join(' and ');break;}
 case 'discriminant':{const d=v.b*v.b-4*v.a*v.c;expected=d>0?'Two distinct real roots':d===0?'One repeated real root':'No real roots';break;}
 case 'ap-nth':{let t=v.a;for(let i=1;i<v.n;i++)t+=v.d;expected=String(t);break;}
 case 'ap-sum':{let sum=0,t=v.a;for(let i=0;i<v.n;i++){sum+=t;t+=v.d;}expected=String(sum);break;}
 case 'distance':expected=String(Math.sqrt((v.x2-v.x1)**2+(v.y2-v.y1)**2));break;
 case 'section':expected=pair((v.n*v.x1+v.m*v.x2)/(v.m+v.n),(v.n*v.y1+v.m*v.y2)/(v.m+v.n));break;
 case 'similarity-lengths':expected=String(v.side2*v.reference2/v.reference1);break;
 case 'tangent-length':expected=String((v.right-v.offset)/v.coefficient);ensure(v.right>0);break;
 case 'trig-ratios':{ensure(v.opposite**2+v.adjacent**2===v.hypotenuse**2);const pairs=[[v.opposite,v.hypotenuse],[v.adjacent,v.hypotenuse],[v.opposite,v.adjacent],[v.hypotenuse,v.opposite],[v.hypotenuse,v.adjacent],[v.adjacent,v.opposite]];expected=fraction(...pairs[v.ratio] as [number,number]);break;}
 case 'trig-standard':{const sin=['0','1/2','√2/2','√3/2','1'],cos=['1','√3/2','√2/2','1/2','0'],tan=['0','√3/3','1','√3','undefined'];expected=[sin,cos,tan][v.ratio][v.angleIndex];break;}
 case 'trig-identity':{ensure(v.numerator>0&&v.denominator>v.numerator);const remaining=v.denominator**2-v.numerator**2;const root=Math.sqrt(remaining);ensure(Number.isInteger(root));expected=fraction(root,v.denominator);break;}
 case 'sector':expected=pi(v.angle/360*(v.kind===0?v.radius**2:2*v.radius),v.kind===0?'square units':'units');break;
 case 'composite-volume':expected=pi(v.radius**2*v.height+2*v.radius**3/3,'cubic units');break;
 case 'grouped-mean':{const f=p.frequencies as number[];let total=0,count=0;f.forEach((frequency,i)=>{for(let j=0;j<frequency;j++){total+=v.lower+i*v.width+v.width/2;count++;}});expected=fraction(total,count);break;}
 case 'probability':{let favourable=0;for(let card=1;card<=v.total;card++)if(v.complement?card%v.divisor!==0:card%v.divisor===0)favourable++;expected=fraction(favourable,v.total);break;}
 default:throw Error('Unsupported question family');
 }
 ensure(answer===expected);return true;
}
export function expandedQuestion(id:string,level:number,n:number):ExpandedQuestion{
 const t=2+n%7,scale=level===3?2+n%3:1,negative=level>1?-1:1;
 let p:Parameters={},prompt='',equation='',expected='',wrong:string[]=[];
 switch(id){
 case 'hcf-lcm':{const h=t,x=h*3,y=h*(level===1?5:7);p={x,y};equation=`${x} and ${y}`;expected=`HCF ${h}, LCM ${x*y/h}`;wrong=[`HCF ${x}, LCM ${x*y}`,`HCF ${h}, LCM ${x*y}`];prompt=`Find the HCF and LCM of ${x} and ${y}. Explain how shared and unshared prime factors determine each.`;break;}
 case 'polynomial-zero':{const r=negative*t,s=t+3,a=scale,c=a*r*s,b=-a*(r+s),candidate=n%2?r:r+1;p={a,b,c,r:candidate};equation=`p(x)=${a}x²+(${b})x+(${c})`;expected=n%2?'Yes, it is a zero':'No, it is not a zero';wrong=[n%2?'No, it is not a zero':'Yes, it is a zero','Every integer is a zero'];prompt=`For ${equation}, is ${candidate} a zero? Explain by substituting and checking the result.`;break;}
 case 'coefficients':case 'quadratic-roots':{const r=negative*t,s=level===3&&n%2?r:t+2,a=scale,b=-a*(r+s),c=a*r*s;p={a,b,c};equation=`${a}x²+(${b})x+(${c})${id==='quadratic-roots'?'=0':''}`;expected=id==='coefficients'?`sum ${r+s}, product ${r*s}`:[...new Set([r,s])].sort((a,b)=>a-b).join(' and ');wrong=id==='coefficients'?[`sum ${-(r+s)}, product ${r*s}`,`sum ${r+s+1}, product ${r*s+1}`]:[String(r+1),String(r+2)];prompt=id==='coefficients'?`For ${equation}, find the sum and product of its zeros. Explain the coefficient signs and why dividing by the leading coefficient matters.`:`Solve ${equation} by factorisation over the reals. Explain why your factors give every root, including any repeated root.`;break;}
 case 'linear-substitution':case 'linear-elimination':case 'linear-consistency':{const x=negative*t,y=t+1,A=scale,B=1,D=1,E=scale+1,C=A*x+B*y,F=D*x+E*y;p={A,B,C,D,E,F};if(id==='linear-consistency'&&n%3!==0){p.D=A*2;p.E=B*2;p.F=C*2+(n%3===2?1:0);}equation=`${p.A}x+${p.B}y=${p.C}; ${p.D}x+${p.E}y=${p.F}`;if(id==='linear-consistency'){expected=n%3===0?'One solution':n%3===1?'Infinitely many solutions':'No solution';wrong=['One solution','No solution','Infinitely many solutions'].filter(s=>s!==expected);prompt=`How many solutions does ${equation} have? Explain how coefficients and constants distinguish intersecting, parallel and coincident lines.`;}else{expected=pair(x,y);wrong=[pair(x+1,y),pair(x,y-1)];prompt=`Solve ${equation} using ${id==='linear-elimination'?'elimination':'substitution'}. Give (x, y), explain the method and check both original equations.`;}break;}
 case 'quadratic-standard':{const a=scale,b=negative*t,c=-(t+1);p={a,b,c};equation=`${a}x²+(${b})x=${-c}`;expected=`a=${a}, b=${b}, c=${c}`;wrong=[`a=${a}, b=${b}, c=${-c}`,`a=${a}, b=${-b}, c=${c}`];prompt=`Write ${equation} in standard form and identify a, b, c. Explain the constant's sign and why a must be nonzero.`;break;}
 case 'discriminant':{const a=scale,b=2*a*t,c=a*t*t+(n%3===0?-a:n%3===1?0:a);p={a,b,c};equation=`${a}x²+${b}x+${c}=0`;expected=n%3===0?'Two distinct real roots':n%3===1?'One repeated real root':'No real roots';wrong=['Two distinct real roots','One repeated real root','No real roots'].filter(s=>s!==expected);prompt=`Determine the nature of the roots of ${equation}. Calculate the discriminant and explain what its sign establishes over the real numbers.`;break;}
 case 'ap-nth':case 'ap-sum':{const a=negative*t,d=level===3&&n%3===0?0:negative*(1+n%5),count=level===1?5+n%4:10+n%11;p={a,d,n:count};equation=`a=${a}, d=${d}, n=${count}`;expected=String(id==='ap-nth'?a+(count-1)*d:count*(2*a+(count-1)*d)/2);wrong=[String(Number(expected)+1),String(Number(expected)-1)];prompt=`An AP has first term ${a}, common difference ${d}. Find ${id==='ap-nth'?`term ${count}`:`the sum of the first ${count} terms`}. Explain ${id==='ap-nth'?'why there are n−1 steps':'how pairing the first and last terms gives the sum'}.`;break;}
 case 'distance':{const x1=-t,y1=negative*(t+1),dx=(level===1?3:5)*scale,dy=(level===1?4:12)*scale,x2=x1+dx,y2=y1-dy;p={x1,y1,x2,y2};equation=`A${pair(x1,y1)}, B${pair(x2,y2)}`;expected=String((level===1?5:13)*scale);wrong=[String(dx+dy),String(dx)];prompt=`Find the distance between ${equation}. Explain how the horizontal and vertical differences form a right triangle.`;break;}
 case 'section':{const m=level===1?1:2+n%3,nn=level===1?1:1+n%2,x1=-t,y1=t,x2=x1+(m+nn)*scale,y2=y1-(m+nn)*(scale+1);p={m,n:nn,x1,y1,x2,y2};equation=`A${pair(x1,y1)}, B${pair(x2,y2)}, AP:PB=${m}:${nn}`;expected=pair(x1+m*scale,y1-m*(scale+1));wrong=[pair(x1+(m+1)*scale,y1-m*(scale+1)),pair(x1,y1)];prompt=`Find P internally dividing ${equation}. Explain which endpoint receives each weight and why P lies between A and B.`;break;}
 case 'similarity-lengths':{const reference1=t,reference2=t*scale*2,side2=t+3;p={reference1,reference2,side2};equation=`AB=${reference1}, DE=${reference2}, BC=${side2}`;expected=String(side2*scale*2);wrong=[String(side2+scale),String(side2)];prompt=`Triangles ABC and DEF are given similar with A↔D, B↔E, C↔F. ${equation}. Find EF and explain the corresponding-side scale factor. You do not need to prove similarity.`;break;}
 case 'tangent-length':{const coefficient=scale+1,offset=level===1?1:-t,x=t+2,right=coefficient*x+offset;p={coefficient,offset,right};equation=`PA=${coefficient}x+(${offset}), PB=${right}`;expected=String(x);wrong=[String(x+1),String(right)];prompt=`PA and PB are tangent lengths from the same external point P to the same circle. ${equation}. Find x and explain why you may equate the lengths.`;break;}
 case 'trig-ratios':{const opposite=(level===1?3:5)*scale,adjacent=(level===1?4:12)*scale,hypotenuse=(level===1?5:13)*scale,ratio=n%6;p={opposite,adjacent,hypotenuse,ratio};const nums=[[opposite,hypotenuse],[adjacent,hypotenuse],[opposite,adjacent],[hypotenuse,opposite],[hypotenuse,adjacent],[adjacent,opposite]];expected=fraction(...nums[ratio] as [number,number]);wrong=['0','1'];equation=`opposite=${opposite}, adjacent=${adjacent}, hypotenuse=${hypotenuse}`;prompt=`Relative to acute angle A in a right triangle, ${equation}. Find ${['sin','cos','tan','cosec','sec','cot'][ratio]} A and explain which two sides define it.`;break;}
 case 'trig-standard':{const angleIndex=n%5,ratio=(Math.floor(n/5)+level-1)%3; p={angleIndex,ratio};const angle=[0,30,45,60,90][angleIndex];const values=[['0','1/2','√2/2','√3/2','1'],['1','√3/2','√2/2','1/2','0'],['0','√3/3','1','√3','undefined']];expected=values[ratio][angleIndex];wrong=['0','1','undefined','1/2'].filter(x=>x!==expected).slice(0,2);equation=`${['sin','cos','tan'][ratio]} ${angle}°`;prompt=`Find ${equation}. Explain using a special triangle, the appropriate endpoint value, or the denominator restriction; do not just recite a table.`;break;}
 case 'trig-identity':{const numerator=level===1?3:5,denominator=level===1?5:13;p={numerator,denominator};expected=fraction(level===1?4:12,denominator);wrong=[fraction(numerator,denominator),'1'];equation=`sin A=${numerator}/${denominator}, A acute`;prompt=`Given ${equation}, find cos A. Explain the identity and why the positive square root is required.`;break;}
 case 'sector':{const radius=6*scale,angle=[60,90,120,180][n%4],kind=n%2;p={radius,angle,kind};const coefficient=kind===0?radius*radius*angle/360:radius*angle/180;expected=pi(coefficient,kind===0?'square units':'units');wrong=[pi(coefficient+1,kind===0?'square units':'units'),pi(coefficient+2,kind===0?'square units':'units')];equation=`radius=${radius}, central angle=${angle}°`;prompt=`For a sector with ${equation}, find its ${kind===0?'area':'arc length'} as a multiple of π. Explain why the angle gives a fraction of the full circle and state the units.`;break;}
 case 'composite-volume':{const radius=3*scale,height=t*scale;p={radius,height};expected=pi(radius*radius*height+2*radius**3/3,'cubic units');wrong=[pi(radius*radius*height+4*radius**3/3,'cubic units'),pi(radius*radius*height,'cubic units')];equation=`radius=${radius}, cylinder height=${height}`;prompt=`A solid cylinder is joined face-to-face to a solid hemisphere of the same radius, with no overlap. ${equation}. Find total volume as a multiple of π. Explain the hemisphere contribution and why volumes add.`;break;}
 case 'grouped-mean':{const lower=level===1?0:10,width=level===3?20:10,frequencies=[t,2*t,3*t];p={lower,width,frequencies};const mids=[lower+width/2,lower+width*1.5,lower+width*2.5];expected=fraction(mids.reduce((sum,m,i)=>sum+m*frequencies[i],0),6*t);wrong=[String(mids[1]),String(mids[2])];equation=frequencies.map((f,i)=>`[${lower+i*width},${lower+(i+1)*width}): ${f}`).join('; ');prompt=`Grouped frequencies are ${equation}. Estimate the mean using the direct method. Explain why class midpoints are weighted by frequencies and why the result is an estimate.`;break;}
 case 'probability':{const total=level===1?6:12+n%9,divisor=level===3&&n%3===0?total+1:level===3&&n%3===1?1:2+n%4,complement=n%2;p={total,divisor,complement};const count=Math.floor(total/divisor);expected=fraction(complement?total-count:count,total);wrong=['0','1','1/2','1/3'].filter(x=>x!==expected).slice(0,2);equation=`cards 1 to ${total}, uniformly random draw`;prompt=`One card is drawn uniformly from cards numbered 1 through ${total}. Find the probability that its number is ${complement?'not ':''}divisible by ${divisor}. Explain the equally likely outcomes and favourable count.`;break;}
 default:throw Error('This concept has no tested question family.');
 }
 verifyExpanded(id,p,expected);
 const options=[...new Set([expected,...wrong])];ensure(options.length===3);
 const shift=n%3;return {prompt,equation,expected,options:[...options.slice(shift),...options.slice(0,shift)],parameters:p};
}
